const resp = $input.first().json || {};
const citas = Array.isArray(resp.citas) ? resp.citas : [];
return citas.map((c) => {
  const [y, m, d] = String(c.fecha || '').split('-');
  const fechaBO = d && m && y ? `${d}/${m}/${y}` : c.fecha;
  return {
    json: {
      citaId: c.id,
      clienteNombre: c.clienteNombre,
      clienteTelefono: c.clienteTelefono || '',
      sucursalNombre: c.sucursalNombre,
      mensajeRecordatorio: `Hola ${c.clienteNombre}, te recordamos tu cita mañana ${fechaBO} a las ${c.hora} para ${c.servicioNombre} en HERMOSA TALITA KUMI (${c.sucursalNombre}). Si necesitas reprogramar o cancelar, hazlo con al menos 2 horas de anticipación.`
    }
  };
});
